import{_ as a,c as e,o as r,a2 as o}from"./chunks/framework.CzULAunO.js";const p=JSON.parse('{"title":"Authenticator","description":"","frontmatter":{},"headers":[],"relativePath":"docs/general-skills/cyber security/Authenticator.md","filePath":"docs/general-skills/cyber security/Authenticator.md","lastUpdated":1766652908000}'),i={name:"docs/general-skills/cyber security/Authenticator.md"};function l(n,t,s,h,u,g){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="authenticator" tabindex="-1"><strong>Authenticator</strong> <a class="header-anchor" href="#authenticator" aria-label="Permalink to &quot;**Authenticator**&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><h3 id="什么是-2fa-为什么要使用它" tabindex="-1">什么是 2FA? 为什么要使用它？ <a class="header-anchor" href="#什么是-2fa-为什么要使用它" aria-label="Permalink to &quot;什么是 2FA? 为什么要使用它？&quot;">​</a></h3><p>2FA（Two-Factor Authentication，双重身份验证）是一种额外的身份验证步骤，和**『密码 + 验证码』登录中的“验证码”类似**，可以在你登录账户时提高安全性。</p><p>相比短信验证码，Authenticator 应用程序（例如 Google Authenticator 等）生成的动态验证码更加安全可靠，因为它们不依赖于手机网络且更难被拦截。</p><h3 id="为什么选择支持同步的-authenticator-应用" tabindex="-1">为什么选择支持同步的 Authenticator 应用？ <a class="header-anchor" href="#为什么选择支持同步的-authenticator-应用" aria-label="Permalink to &quot;为什么选择支持同步的 Authenticator 应用？&quot;">​</a></h3><p>通常情况下，大部分 2FA 应用程序不会将账号同步到云端，以确保安全性。然而，这种方式也存在风险——如果你丢失了手机，可能会面临无法访问所有启用了 2FA 的账户的问题。为了解决这个问题，越来越多的 Authenticator 应用开始支持账号备份和同步功能，让用户在多个设备间安全地恢复 2FA 数据。</p><h2 id="推荐的-authenticator-应用程序" tabindex="-1">推荐的 Authenticator 应用程序 <a class="header-anchor" href="#推荐的-authenticator-应用程序" aria-label="Permalink to &quot;推荐的 Authenticator 应用程序&quot;">​</a></h2><h3 id="keepass2android" tabindex="-1"><a href="https://github.com/PhilippC/keepass2android" target="_blank" rel="noreferrer">Keepass2Android</a> <a class="header-anchor" href="#keepass2android" aria-label="Permalink to &quot;[Keepass2Android](https://github.com/PhilippC/keepass2android)&quot;">​</a></h3><ul><li><a href="https://github.com/PhilippC/keepass2android" target="_blank" rel="noreferrer">GitHub</a></li><li><strong>优点</strong>： <ul><li>密码管理</li><li>自动填充</li><li>密码生成</li><li>OTP 等</li></ul></li><li><strong>缺点</strong>： <ul><li>初次使用可能不太会用，OTP 功能藏的有点深</li></ul></li><li><strong>其他</strong>：OTP 功能只是它的冰山一角，密码填充、密码管理、密码生成等等他都能做到，基本上可以说是安卓系统功能最全面的密码管理软件了</li></ul><h3 id="aegis-authenticator" tabindex="-1">Aegis Authenticator <a class="header-anchor" href="#aegis-authenticator" aria-label="Permalink to &quot;Aegis Authenticator&quot;">​</a></h3><ul><li><a href="https://github.com/beemdevelopment/Aegis" target="_blank" rel="noreferrer">GitHub</a></li><li>F-Droid（请先使用 <a href="https://mirror.nju.edu.cn/fdroid/repo/?fingerprint=43238D512C1E5EB2D6569F4A3AFBF5523418B82E0A3ED1552770ABB9A9C9CCAB" target="_blank" rel="noreferrer">此链接</a> 将 F-Droid 的南京大学中国镜像添加到你的软件，再搜索 <code>com.beemdevelopment.aegis</code></li><li><strong>特点</strong>: 免费开源，支持本地加密备份（如将备份导出至 Google Drive、Dropbox 等实现手动同步）。</li><li><strong>优点</strong>: 强大的加密备份功能，无广告，开源透明性高，隐私友好。</li><li><strong>缺点</strong>: 不支持自动云同步，需要手动导入导出备份文件。</li></ul><h3 id="authy" tabindex="-1"><a href="https://play.google.com/store/apps/details?id=com.authy.authy&amp;hl=zh&amp;gl=US" target="_blank" rel="noreferrer">Authy</a> <a class="header-anchor" href="#authy" aria-label="Permalink to &quot;[Authy](https://play.google.com/store/apps/details?id=com.authy.authy&amp;hl=zh&amp;gl=US)&quot;">​</a></h3><ul><li><a href="https://play.google.com/store/apps/details?id=com.authy.authy" target="_blank" rel="noreferrer">Google Play</a></li><li><strong>特点</strong>: 支持云备份和多设备同步，易于跨设备恢复 2FA 数据，支持 PIN 码和指纹保护。</li><li><strong>优点</strong>: 界面简洁，使用方便，支持所有常见的 2FA 账户。</li><li><strong>缺点</strong>: 需要使用手机号进行注册，且云端备份有潜在的隐私风险。</li></ul><h3 id="raivo-otp" tabindex="-1"><a href="https://github.com/raivo-otp/" target="_blank" rel="noreferrer">Raivo OTP</a> <a class="header-anchor" href="#raivo-otp" aria-label="Permalink to &quot;[Raivo OTP](https://github.com/raivo-otp/)&quot;">​</a></h3><ul><li><a href="https://github.com/raivo-otp/raivo-otp-android" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://apps.apple.com/us/app/raivo-authenticator/id1459042137" target="_blank" rel="noreferrer">App Store</a></li><li><strong>特点</strong>: 开源，专注于简单实用。支持加密备份（可选择备份到 iCloud 或 Google Drive），适合希望轻量化的用户。</li><li><strong>优点</strong>: 界面简洁；开源透明；备份文件加密；使用便捷。</li><li><strong>缺点</strong>: 功能相对简单；不支持自动同步；只有 iOS 版本</li></ul><h3 id="microsoft-authenticator" tabindex="-1"><a href="https://play.google.com/store/apps/details?id=com.azure.authenticator" target="_blank" rel="noreferrer">Microsoft Authenticator</a> <a class="header-anchor" href="#microsoft-authenticator" aria-label="Permalink to &quot;[Microsoft Authenticator](https://play.google.com/store/apps/details?id=com.azure.authenticator)&quot;">​</a></h3><p>微软已逐步开始移除常用功能，鉴于其功能的缺失以及后续更新可能存在的对软件功能的破坏性而不再推荐</p><h3 id="google-authenticator" tabindex="-1"><a href="https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2" target="_blank" rel="noreferrer">Google Authenticator</a> <a class="header-anchor" href="#google-authenticator" aria-label="Permalink to &quot;[Google Authenticator](https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2)&quot;">​</a></h3><ul><li><a href="https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2" target="_blank" rel="noreferrer">Google Play</a></li><li><strong>特点</strong>: 支持双重验证（TOTP），目前已推出了账户同步功能。</li><li><strong>优点</strong>: <ul><li><strong>简单便捷</strong>: 界面简洁，操作非常简单，适合初学者。</li><li><strong>最近更新的同步功能</strong>: 现在支持账户同步，用户可以选择将 2FA 数据备份到 Google 账号中，以便在新设备上恢复。</li></ul></li><li><strong>缺点</strong>: <ul><li><strong>隐私担忧</strong>: 账户同步功能需要依赖 Google 账户，如果对隐私有高要求的用户可能会有顾虑。</li><li><strong>功能简单</strong>: 没有太多高级功能，如密码锁定等安全增强功能。</li></ul></li></ul><h3 id="keeotp2" tabindex="-1"><a href="https://github.com/tiuub/KeeOtp2" target="_blank" rel="noreferrer">KeeOtp2</a> <a class="header-anchor" href="#keeotp2" aria-label="Permalink to &quot;[KeeOtp2](https://github.com/tiuub/KeeOtp2)&quot;">​</a></h3><ul><li><strong>特点</strong>: KeeOtp2 是一个 KeePass 插件，支持生成基于时间的一次性密码（TOTP），适用于需要在 KeePass 中直接管理 2FA 密钥的用户。</li><li><strong>优点</strong>: <ul><li>集成到 KeePass 中，方便管理密码和 2FA 密钥。</li><li>开源透明，适合注重隐私的用户。</li></ul></li><li><strong>缺点</strong>: <ul><li>依赖于 KeePass，适用范围有限。</li><li>功能相对单一，仅支持 TOTP。</li></ul></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ul><li><strong>Google Authenticator</strong> 非常稳定和可靠，适合与它们自家产品和服务生态圈配合使用。</li><li>如果你注重隐私和开源，可能更偏好像 <strong>Aegis</strong> 这样的开源应用。如果你需要同步功能且不介意使用大公司的服务，<strong>Google Authenticator</strong> 是更为便捷的选择。 使用这些工具时要谨慎备份密钥，以防在设备丢失或损坏时无法恢复 2FA 账户。</li></ul>',24)]))}const d=a(i,[["render",l]]);export{p as __pageData,d as default};
